import holyWeekScripture from "./holyWeekScripture.json";
import type { SacredMoment } from "@/types/holyWeek";

const prayer = (text: string) => text;
const meditation = (title: string, theme: string, reference: string) => [
  `Stay with ${title}. Let the Gospel scene become a doorway into prayer, not an invitation to speculate beyond what has been given to us. In ${reference}, the Church receives a glimpse of the love of Christ: a love that is free, steady, and turned toward the Father.`,
  `Bring your own life into this moment. Notice where you are being asked to receive, surrender, remain faithful, or begin again. ${theme} is not an idea to master but a grace to ask for. Sit quietly before Jesus and allow His mercy to meet the place in you that most needs Him today.`,
];

type Seed = Omit<SacredMoment, "sequence" | "meditation" | "reflectionQuestions" | "scripturePassages"> & { meditation?: string[]; reflectionQuestions?: string[] };
const seeds: Seed[] = [
  { id: "palm-sunday", liturgicalDay: "Palm Sunday", timeCertainty: "untimed", title: "The King Enters Jerusalem", subtitle: "Welcome the King", scriptureReference: "Matthew 21:1–11", theme: "Welcome the King", virtue: "Humility", responsePrayer: prayer("Lord Jesus, I welcome You as my King. Enter the Jerusalem of my heart and remove whatever keeps me from belonging completely to You. Give me the humility to follow You not only when the road is joyful, but when it leads toward the Cross. Amen."), imageDescription: "Jesus enters Jerusalem upon a donkey in warm afternoon light, palm branches framing a peaceful crowd.", imageAlt: "A peaceful depiction of Jesus entering Jerusalem on a donkey", visualMood: "daylight", dayOffset: -7 },
  { id: "holy-monday", liturgicalDay: "Holy Monday", timeCertainty: "untimed", title: "Love Poured Out at Bethany", subtitle: "Love Without Measure", scriptureReference: "John 12:1–11", theme: "Love Without Measure", virtue: "Generosity", responsePrayer: prayer("Jesus, teach me to love You without calculating the cost. May I pour out my time, attention, possessions, and heart for You without fear of waste. Let my life become an offering of love that quietly leads others toward You. Amen."), imageDescription: "Mary of Bethany kneels before Jesus in an intimate candlelit home beside an alabaster vessel.", imageAlt: "Mary of Bethany offering love to Jesus in a candlelit home", visualMood: "candlelight", dayOffset: -6 },
  { id: "holy-tuesday", liturgicalDay: "Holy Tuesday", timeCertainty: "untimed", title: "Before the Rooster Crows", subtitle: "Know My Weakness", scriptureReference: "John 13:21–38", theme: "Know My Weakness", virtue: "Vigilance", responsePrayer: prayer("Lord Jesus, You know my weakness more completely than I know it myself. Protect me from presumption and teach me to depend upon Your grace. When following You becomes difficult, give me the courage to remain faithful. Amen."), imageDescription: "Peter remains close to Jesus while a subtle darkness gathers, a devotional foreshadowing rather than a literal chronology.", imageAlt: "Peter near Jesus as shadows gather around them", visualMood: "candlelight", dayOffset: -5 },
  { id: "spy-wednesday", liturgicalDay: "Spy Wednesday", timeCertainty: "untimed", title: "Thirty Pieces of Silver", subtitle: "What Is Christ Worth to Me?", scriptureReference: "Matthew 26:14–25", theme: "What Is Christ Worth to Me?", virtue: "Fidelity", responsePrayer: prayer("Jesus, guard my heart from slowly trading You for lesser things. Reveal every compromise by which I place comfort, pride, possessions, or approval before You. Give me a faithful heart that chooses You again and again. Amen."), imageDescription: "Judas stands alone in shadow with silver in his hand while warm light remains behind him.", imageAlt: "Judas holding silver in shadow with warm light behind him", visualMood: "stone", dayOffset: -4 },
  { id: "last-supper", liturgicalDay: "Holy Thursday", displayTime: "6:00 PM", timeCertainty: "approximate", title: "The Last Supper", subtitle: "He Gives Himself", scriptureReference: "Luke 22:14–20; John 13:1–15", theme: "He Gives Himself", virtue: "Reverence", openingPrayer: prayer("Lord Jesus Christ, You gathered with Your apostles in the upper room on the night You were betrayed, and there, in perfect love, You gave us the gift of Yourself in the Most Holy Eucharist. As I enter this sacred hour in prayer, I ask You to draw me close to Your Heart. Let me understand more deeply the mystery of Your love poured out in the Blessed Sacrament. Help me to reverence the priesthood, which You established to feed us with Your Body and Blood until the end of time. Amen."), meditation: ["It is evening. Jesus reclines at table with His chosen Twelve. The air is heavy with the knowledge of betrayal, yet Jesus does not recoil. Instead, He leans in with love. He takes bread in His sacred hands, blesses it, breaks it, and says words that echo through eternity: ‘This is My Body.’ He hands it to His disciples, not as a symbol, but as a gift—His very self.", "He looks into their eyes, and into ours, with tenderness. He knows what lies ahead—Gethsemane, the Cross, the tomb—but still, He chooses to remain with us in the hidden form of bread and wine. In that moment, He institutes the Eucharist and ordains His apostles to be priests, to carry this mystery through every age.", "This is not just a meal. It is a covenant. A wedding feast of the Lamb. Jesus becomes our food, our strength, our constant companion. The upper room becomes the altar of eternity, and every Mass is a return to that night, where love offered itself in silence and surrender."], reflectionQuestions: ["Do I truly believe that Jesus is present, Body, Blood, Soul, and Divinity, in the Eucharist?", "How do I approach Mass and Communion—casually or with reverence and awe?", "Do I pray for priests and support their sacred mission to bring Christ to us?"], responsePrayer: prayer("Jesus, You gave Yourself to me without reserve. Forgive me for the times I have received You unworthily, or treated Your presence lightly. Increase my faith in Your Real Presence in the Eucharist. Help me to hunger for You in the Blessed Sacrament and to love You with my whole heart. Strengthen all priests to be holy, faithful, and courageous servants of the altar. Let Your love transform my soul every time I receive You. Amen."), virtueDescription: "Deep respect and awe for God, especially in the Blessed Sacrament.", virtuePrayer: prayer("Lord Jesus, You are truly present in the Eucharist—hidden, yet fully alive. Grant me the virtue of holy reverence. Let me never grow cold or indifferent before You. Teach me to bow my head, to silence my heart, and to adore You with every fiber of my being. May my every approach to Your altar be marked with awe, humility, and love. Amen."), imageDescription: "The Upper Room glows with warm candlelight; Jesus is centered with bread and chalice, while service is suggested nearby.", imageAlt: "Jesus and the disciples gathered in the candlelit Upper Room", visualMood: "candlelight", optionalFeature: "remain", hour: 18, minute: 0, dayOffset: -3 },
  { id: "gethsemane", liturgicalDay: "Holy Thursday", displayTime: "8:00 PM", timeCertainty: "approximate", title: "Gethsemane", subtitle: "Not My Will", scriptureReference: "Matthew 26:36–46; Luke 22:39–46", theme: "Not My Will", virtue: "Surrender", responsePrayer: prayer("Jesus in Your agony, remain with me when obedience becomes difficult. Bring every fear I carry into Your prayer to the Father. Teach my heart to say with Yours: not my will, but the Father’s will be done. Amen."), imageDescription: "Jesus kneels beneath ancient olive trees beneath an indigo sky while sleeping disciples remain distant.", imageAlt: "Jesus praying beneath olive trees in Gethsemane", visualMood: "indigo", optionalFeature: "watch", hour: 20, minute: 0, dayOffset: -3 },
  { id: "betrayed-arrested", liturgicalDay: "Holy Thursday", displayTime: "9:00 PM", timeCertainty: "approximate", title: "Betrayed and Arrested", subtitle: "Faithful When Betrayed", scriptureReference: "Matthew 26:47–56; John 18:1–11", theme: "Faithful When Betrayed", virtue: "Faithfulness", responsePrayer: prayer("Jesus, You received betrayal without ceasing to love. Forgive every way I have betrayed You through sin, silence, or compromise. When others wound me, keep bitterness from ruling my heart and teach me the costly freedom of mercy. Amen."), imageDescription: "Judas approaches Jesus among olive trees as soldiers emerge with torches; Christ remains calm.", imageAlt: "Jesus meeting Judas and the soldiers in the garden", visualMood: "indigo", hour: 21, minute: 0, dayOffset: -3 },
  { id: "annas-caiaphas", liturgicalDay: "Holy Thursday", displayTime: "10:00 PM", timeCertainty: "approximate", title: "Before Annas and Caiaphas", subtitle: "Truth Under Accusation", scriptureReference: "John 18:12–24; Matthew 26:57–68", theme: "Truth Under Accusation", virtue: "Meekness", responsePrayer: prayer("Jesus, when I am misunderstood, criticized, or falsely judged, keep me from becoming consumed by anger. Give me strength without harshness and courage without pride. May truth and charity govern my words. Amen."), imageDescription: "Christ stands bound in a torchlit stone chamber, composed amid agitation.", imageAlt: "Christ standing bound before authorities in a stone chamber", visualMood: "stone", hour: 22, minute: 0, dayOffset: -3 },
  { id: "peter-denies", liturgicalDay: "Holy Thursday", displayTime: "11:00 PM", timeCertainty: "approximate", title: "Peter Denies Jesus", subtitle: "The Look of Mercy", scriptureReference: "Luke 22:54–62", theme: "The Look of Mercy", virtue: "Contrition", responsePrayer: prayer("Jesus, You know every promise I have broken and every moment I have been ashamed to belong to You. Look upon me as You looked upon Peter—not to destroy me, but to call me home. Give me true sorrow for sin and confidence in Your mercy. Amen."), imageDescription: "Peter beside a courtyard fire looks toward Jesus in the distance; their meeting of eyes is central.", imageAlt: "Peter beside a fire looking toward Jesus across the courtyard", visualMood: "stone", hour: 23, minute: 0, dayOffset: -3 },
  { id: "mocked-night", liturgicalDay: "Good Friday", displayTime: "1:00 AM", timeCertainty: "approximate", title: "Mocked Through the Night", subtitle: "The Silent Christ", scriptureReference: "Luke 22:63–65", theme: "The Silent Christ", virtue: "Endurance", responsePrayer: prayer("Jesus, mocked and rejected, remain near those who suffer unnoticed and alone tonight. When I feel forgotten, remind me that You entered that darkness before me. Give me grace to remain faithful when prayer feels empty and consolation disappears. Amen."), imageDescription: "Jesus remains bound in deep shadow after being mocked, with a faint suggestion of approaching dawn.", imageAlt: "Jesus bound in shadow after being mocked", visualMood: "stone", hour: 1, minute: 0, dayOffset: -2 },
  { id: "pilate-herod", liturgicalDay: "Good Friday", displayTime: "5:00 AM", timeCertainty: "approximate", title: "Before Pilate and Herod", subtitle: "The Innocent One Is Judged", scriptureReference: "Luke 23:1–12", theme: "The Innocent One Is Judged", virtue: "Integrity", responsePrayer: prayer("Jesus, You stood before earthly power without abandoning truth. Free me from the need for approval and from the fear that keeps me silent when I should do what is right. Make me faithful to You whether I am praised or rejected. Amen."), imageDescription: "Jesus stands before Pilate in cold predawn light among Roman stone architecture.", imageAlt: "Jesus standing before Pilate in cold predawn light", visualMood: "stone", hour: 5, minute: 0, dayOffset: -2 },
  { id: "scourged-crowned", liturgicalDay: "Good Friday", displayTime: "7:00 AM", timeCertainty: "approximate", title: "Scourged, Crowned and Condemned", subtitle: "Behold the Man", scriptureReference: "John 19:1–16", theme: "Behold the Man", virtue: "Humility", responsePrayer: prayer("Jesus, crowned with thorns, strip away the pride by which I seek recognition and control. Teach me that my worth is found not in applause but in belonging to You. May Your wounded face become the face I seek above every earthly honor. Amen."), imageDescription: "Christ wears the purple cloak and crown of thorns before Pilate in pale morning light; reverent and non-graphic.", imageAlt: "Christ crowned with thorns before Pilate", visualMood: "stone", hour: 7, minute: 0, dayOffset: -2 },
  { id: "carries-cross", liturgicalDay: "Good Friday", displayTime: "8:00 AM", timeCertainty: "approximate", title: "Jesus Carries the Cross", subtitle: "Take Up Your Cross", scriptureReference: "John 19:16–17; Luke 23:26–32", theme: "Take Up Your Cross", virtue: "Perseverance", responsePrayer: prayer("Jesus, when my cross feels heavier than I can bear, remind me that You walk before me. Help me carry what I cannot change with patience, courage, and love. Unite my suffering to Yours so that nothing in my life is wasted. Amen."), imageDescription: "On a narrow Jerusalem street, Simon of Cyrene begins to assist Jesus as dust catches morning light.", imageAlt: "Jesus carrying the Cross with Simon of Cyrene beginning to help", visualMood: "stone", hour: 8, minute: 0, dayOffset: -2 },
  { id: "crucifixion-begins", liturgicalDay: "Good Friday", displayTime: "9:00 AM", timeCertainty: "scriptural", title: "The Crucifixion Begins", subtitle: "Love Is Lifted Up", scriptureReference: "Mark 15:25–32", theme: "Love Is Lifted Up", virtue: "Sacrificial Love", responsePrayer: prayer("Crucified Jesus, Your love did not turn back when love became costly. Teach me to give without keeping score, to forgive when wounded, and to serve when no one sees. Draw me beneath Your Cross and make my life an offering of love. Amen."), imageDescription: "A wide, reverent Calvary composition as the Cross is raised beneath a morning sky.", imageAlt: "The Cross raised at Calvary beneath a morning sky", visualMood: "calvary", hour: 9, minute: 0, dayOffset: -2 },
  { id: "darkness-land", liturgicalDay: "Good Friday", displayTime: "12:00 PM", timeCertainty: "scriptural", title: "Darkness Covers the Land", subtitle: "Remain With Him", scriptureReference: "Matthew 27:45–49", theme: "Remain With Him", virtue: "Faith in Darkness", responsePrayer: prayer("Jesus, when I cannot see what You are doing, keep me from abandoning You. Enter every darkness in my heart with the hidden light of Your presence. Give me faith that remains even when understanding fails. Amen."), imageDescription: "Calvary beneath a darkened midday sky in charcoal and blue-black; Mary remains beneath the Cross.", imageAlt: "Calvary beneath a darkened midday sky", visualMood: "calvary", optionalFeature: "calvary", hour: 12, minute: 0, dayOffset: -2 },
  { id: "jesus-dies", liturgicalDay: "Good Friday", displayTime: "3:00 PM", timeCertainty: "scriptural", title: "Jesus Dies on the Cross", subtitle: "It Is Consummated", scriptureReference: "Luke 23:44–46; John 19:28–30", theme: "It Is Consummated", virtue: "Total Surrender", responsePrayer: prayer("Jesus Crucified, You held nothing back from me. At the hour of Your death, I place my sins, fears, wounds, future, and life beneath Your Cross. Receive all that I am and teach me to live entirely for You. Amen."), imageDescription: "Immediately after Christ's death, the world is still and the Cross is subtly illuminated against darkness.", imageAlt: "The still Cross after Jesus gives His life", visualMood: "calvary", optionalFeature: "death", hour: 15, minute: 0, dayOffset: -2 },
  { id: "taken-down", liturgicalDay: "Good Friday", displayTime: "4:00 PM", timeCertainty: "approximate", title: "Jesus Is Taken Down", subtitle: "The Pietà", scriptureReference: "John 19:38–40", theme: "The Pietà", virtue: "Compassion", responsePrayer: prayer("Blessed Mother, teach me to remain near Jesus when love brings sorrow. Jesus, place within me a compassionate heart that does not flee from the suffering of another. May I receive You with tenderness and reverence. Amen."), imageDescription: "A Pietà-inspired scene at sunset, with Mary receiving Jesus while Joseph and Nicodemus remain nearby.", imageAlt: "Mary receiving the body of Jesus at the foot of the Cross", visualMood: "calvary", hour: 16, minute: 0, dayOffset: -2 },
  { id: "laid-tomb", liturgicalDay: "Good Friday", displayTime: "5:00 PM", timeCertainty: "approximate", title: "Jesus Is Laid in the Tomb", subtitle: "The Stone Is Rolled Shut", scriptureReference: "Matthew 27:57–61; John 19:38–42", theme: "The Stone Is Rolled Shut", virtue: "Hope", responsePrayer: prayer("Jesus, when something in my life appears finished, buried, or beyond repair, keep hope alive within me. Bury with You everything that must die in me—sin, pride, fear, and resentment. Prepare me for the new life that only You can give. Amen."), imageDescription: "Joseph and Nicodemus bring Christ into the garden tomb as Good Friday's final amber light disappears.", imageAlt: "Jesus being laid in the garden tomb at dusk", visualMood: "silence", hour: 17, minute: 0, dayOffset: -2 },
  { id: "sacred-silence", liturgicalDay: "Holy Saturday", timeCertainty: "untimed", title: "The Day of Sacred Silence", subtitle: "God Works in Silence", scriptureReference: "Matthew 27:62–66; John 19:41–42", theme: "God Works in Silence", virtue: "Patient Hope", responsePrayer: prayer("Jesus, teach me not to fear the silence between prayer and its answer. When I cannot see You working, keep me faithful beside the sealed tomb. Give me the patient hope of Mary, trusting that the Father remains faithful even when everything appears lost. Amen."), imageDescription: "A sealed tomb in the quiet of morning, with cool stone, mist, and muted blue-gray tones.", imageAlt: "The sealed tomb in the quiet of Holy Saturday", visualMood: "silence", optionalFeature: "silence", dayOffset: -1 },
  { id: "descends-dead", liturgicalDay: "Holy Saturday", timeCertainty: "untimed", title: "Christ Descends to the Dead", subtitle: "No Darkness Is Beyond Christ", scriptureReference: "1 Peter 3:18–20; 1 Peter 4:6", theme: "No Darkness Is Beyond Christ", virtue: "Hope", responsePrayer: prayer("Lord Jesus, no depth is beyond the reach of Your victory. Enter the hidden places of my heart where fear, sin, grief, or shame have been buried. Let Your light penetrate them and lead me into the freedom won by Your Cross. Amen."), imageDescription: "A symbolic Christ descends into darkness as shattered gates lie beneath Him and a diverse assembly of waiting figures turns toward the light.", imageAlt: "Christ entering the realm of the dead with victorious light among a diverse assembly", visualMood: "silence", dayOffset: -1 },
  { id: "empty-tomb", liturgicalDay: "Easter Sunday", displayTime: "Before dawn", timeCertainty: "scriptural", title: "The Empty Tomb", subtitle: "The Stone Is Rolled Away", scriptureReference: "John 20:1–10; Luke 24:1–12", theme: "The Stone Is Rolled Away", virtue: "Faith", responsePrayer: prayer("Risen Jesus, roll away every stone that keeps my heart closed to You. Give me faith to enter the empty tomb and believe that death does not have the final word. Raise me from the habits and sins that keep me from living fully in You. Amen."), imageDescription: "The view from inside the tomb toward the first line of golden dawn; burial cloths remain inside.", imageAlt: "Golden dawn seen from inside the empty tomb", visualMood: "dawn", dayOffset: 0 },
  { id: "mary-name", liturgicalDay: "Easter Sunday", timeCertainty: "untimed", title: "Jesus Calls Mary by Name", subtitle: "Called by Name", scriptureReference: "John 20:11–18", theme: "Called by Name", virtue: "Joy", responsePrayer: prayer("Risen Lord, call me again by name. Find me where sorrow, confusion, or disappointment have blinded me to Your presence. Give me the joy of knowing that You are alive and the courage to carry that Good News into the world. Amen."), imageDescription: "Mary Magdalene turns toward the risen Jesus in a garden filled with sunrise.", imageAlt: "Mary Magdalene turning toward the risen Jesus in the garden", visualMood: "dawn", dayOffset: 0 },
  { id: "emmaus", liturgicalDay: "Easter Sunday", displayTime: "Easter afternoon", timeCertainty: "untimed", title: "The Road to Emmaus", subtitle: "Our Hearts Were Burning", scriptureReference: "Luke 24:13–35", theme: "Our Hearts Were Burning", virtue: "Faith", responsePrayer: prayer("Risen Jesus, walk beside me when disappointment makes You difficult to recognize. Open the Scriptures to me and set my heart on fire with Your truth. Stay with me, Lord, and let me recognize Your presence in the breaking of bread. Amen."), imageDescription: "Jesus walks between two disciples toward Emmaus in late-afternoon golden light.", imageAlt: "Jesus walking with two disciples on the road to Emmaus", visualMood: "dawn", optionalFeature: "emmaus", dayOffset: 0 },
  { id: "peace-be-to-you", liturgicalDay: "Easter Sunday", displayTime: "Easter evening", timeCertainty: "untimed", title: "Peace Be to You", subtitle: "From Fear to Mission", scriptureReference: "John 20:19–23; Luke 24:36–49", theme: "From Fear to Mission", virtue: "Mission", responsePrayer: prayer("Risen Jesus, enter the locked rooms of my heart. Speak Your peace over my fear, breathe Your Spirit into my life, and send me into the world as Your witness. May the joy of Your Resurrection shape the way I live, love, forgive, and serve. Amen."), imageDescription: "The risen Jesus appears among the apostles in the Upper Room, extending His hands in peace.", imageAlt: "The risen Jesus appearing among the apostles in the Upper Room", visualMood: "dawn", dayOffset: 0 },
];


