const approvedEnhancements: Record<string, Partial<SacredMoment>> = {
  gethsemane: { event: "Jesus enters deep anguish as He begins His Passion", location: "Mount of Olives, Gethsemane", openingPrayer: prayer("Lord Jesus Christ, as I enter this hour of Your agony, I ask for the grace to remain awake with You, to pray with You, and to share in Your sorrow. Help me not to turn away from Your suffering, but to stay near You with a heart full of love, reverence, and sorrow for sin. Send Your Spirit to awaken my soul. Amen."), virtue: "Obedience to the Will of God", virtueDescription: "Trusting the Father when His will is hard or mysterious.", virtuePrayer: prayer("Heavenly Father, grant me holy obedience. When Your will is hard or mysterious, give me trust to accept it with love. Let my life echo the prayer of Your Son in Gethsemane. Through Christ our Lord. Amen.") },
  "betrayed-arrested": { event: "Jesus is betrayed by Judas and arrested", timeRange: "9:00 PM – 10:00 PM", openingPrayer: prayer("Lord Jesus Christ, As I come before You in this hour of betrayal, I ask for the grace to remain near You. Open my heart to enter into this moment in the garden—where You were abandoned, kissed by betrayal, and handed over in silence. Let me not rush past this scene, but dwell with You, suffer with You, and learn to love You more deeply. Holy Spirit, enlighten my mind and stir my heart, that this meditation may not be mere words, but a living encounter with the sorrowful love of my Savior. Amen."), meditation: ["It is night. The garden, once a place of prayer and surrender, now becomes a place of betrayal. Jesus stands calm, resolute. He has just finished weeping and sweating blood. He has surrendered to the Father’s will. Now the hour has come.", "Judas appears—one of the twelve, one who walked closely with Jesus, shared meals, and heard His voice. And yet, he comes not as a friend, but as a traitor, leading a mob armed with clubs and swords. He betrays the Lord with a kiss—a gesture meant for love, twisted into a tool for treachery.", "Jesus does not resist. He does not rebuke. He says, “Friend, do what you came for.” Even in betrayal, Jesus calls Judas “friend.” Here is divine mercy laid bare—rejected, misunderstood, yet offered freely.", "As the mob seizes Jesus, the disciples flee. He is alone. The chains go around His wrists, but He is the one who gives Himself. This is not the defeat of God, but the triumph of love."], reflectionQuestions: ["Have I ever betrayed the Lord through my choices, my silence, or my sin?", "Do I sometimes serve Christ outwardly, like Judas, while hiding selfish motives within?", "When I am wounded by others’ betrayal or abandonment, do I respond with mercy or bitterness?"], responsePrayer: prayer("Jesus, You were betrayed by a friend, and yet You did not resist. You surrendered to suffering out of love for me. Forgive me for the times I have betrayed You—through sin, neglect, or compromise. Teach me to be faithful in small and hidden ways. In moments of pain and rejection, help me to respond not with bitterness, but with mercy. Let me never be afraid to follow You, even when the path is marked with darkness. Stay with me, Lord, and give me a heart that loves You more than comfort or approval. Amen."), virtueDescription: "Faithfulness means remaining loyal to God in all circumstances—especially when it costs something. It is the quiet endurance of love, the decision to stay when it would be easier to leave.", virtuePrayer: prayer("Lord Jesus, You remained faithful to the Father even when You were abandoned, arrested, and betrayed. Grant me the grace of faithfulness—to love You not only in joy, but in sorrow, not only in light, but in darkness. Strengthen me when I am tempted to flee, to deny, or to compromise. Let my yes to You be constant and true. In every choice, may I remain with You. Amen.") },
  "annas-caiaphas": { event: "Jesus is taken to the house of Annas and then to Caiaphas", timeRange: "10:00 PM – 11:00 PM", openingPrayer: prayer("Lord Jesus, as I enter this hour of Your Passion, open my eyes to see Your suffering and my heart to love You more deeply. Strengthen my resolve to be faithful when the world turns against You. Amen."), virtueDescription: "The strength to be gentle, especially in the face of provocation or injustice.", virtuePrayer: prayer("Lord Jesus, meek and humble of heart, teach me to imitate Your quiet strength. When I am tempted to react in anger or pride, fill me with the peace of Your Spirit. Amen.") },
  "peter-denies": { event: "Jesus before the Sanhedrin and Peter denies Him", timeRange: "11:00 PM – 1:00 AM", openingPrayer: prayer("Lord Jesus Christ, as I enter this moment when You stood unjustly accused and abandoned, open my heart to understand Your silence, dignity, and mercy. Let this meditation deepen my love for You. Amen."), virtue: "Courage", virtueDescription: "Standing for what is right even when afraid or criticized.", virtuePrayer: prayer("Lord Jesus, give me courage to stand for what is right and never be ashamed of You. Strengthen my heart to live boldly for Your glory. Amen.") },
  "mocked-night": { event: "Jesus is imprisoned overnight, beaten, and mocked", timeRange: "1:00 AM – 5:00 AM", openingPrayer: prayer("Lord Jesus, as I enter this sacred hour of Your Passion, grant me the grace to stay with You in loneliness and let Your suffering change my heart. Amen."), virtueDescription: "Remaining faithful to Christ in prayer and love when consolation disappears.", virtuePrayer: prayer("Lord Jesus, You were faithful unto death. Teach me to remain steadfast in suffering, silence, and rejection, constant in grace. Amen.") },
  "pilate-herod": { event: "Trial before Pilate and Herod", timeRange: "5:00 AM – 7:00 AM", openingPrayer: prayer("Lord Jesus, as I meditate on the trial You endured, open my heart to Your silence, meekness, and unwavering obedience. Lead me to reverence, repentance, and love. Amen."), virtueDescription: "Strength under control: calm in adversity without bitterness or revenge.", virtuePrayer: prayer("Lord Jesus, meek and humble of heart, teach me to surrender pride and trust in Your defense. Let my strength be rooted in peace and my words shaped by patience. Amen.") },
  "scourged-crowned": { event: "Jesus is scourged, crowned with thorns, and condemned", timeRange: "7:00 AM – 7:59 AM", openingPrayer: prayer("Lord Jesus Christ, as I contemplate Your scourging, crowning, and condemnation, give me reverence and sorrow. Pierce my soul with compassion and draw me closer to You. Amen."), virtue: "Humility", virtueDescription: "Desiring God's approval rather than the applause of others.", virtuePrayer: prayer("Lord Jesus, meek and humble of heart, teach me to be content to be small if it means being closer to You. Clothe me in the humility of the Cross. Amen.") },
  "carries-cross": { event: "Jesus carries His Cross", timeRange: "8:00 AM – 9:00 AM", openingPrayer: prayer("Lord Jesus Christ, at this hour You accepted the instrument of Your death. Grant me grace to carry my crosses with trust, courage, and love. Amen."), virtueDescription: "The quiet strength that presses forward when it is easier to give up.", virtuePrayer: prayer("Lord Jesus, You did not turn back when the Cross grew heavy. Give me grace to persevere in faith, virtue, and love when the road is long. Amen.") },
  "crucifixion-begins": { event: "The Crucifixion begins — the Third Hour", timeRange: "9:00 AM – 11:59 AM", timelineLabel: "Passion of Christ Timeline", openingPrayer: prayer("Lord Jesus Christ, as the third hour dawns, help me to stand with You on Calvary in silence, awe, sorrow, and gratitude. Amen."), virtueDescription: "Christ gave all. Choose self-giving love, especially when it is difficult or unnoticed.", virtuePrayer: prayer("Lord Jesus, teach me sacrificial love: to serve when tired, give when it costs, and forgive when wounded. Let every act of love be joined to Your Cross. Amen.") },
  "darkness-land": { event: "Darkness covered the land", timeRange: "12:00 PM – 2:59 PM", timelineLabel: "Passion of Christ Timeline", openingPrayer: prayer("Jesus, Light of the World, help me remain at the foot of the Cross in this hour of mystery, watching, waiting, and weeping. Amen."), virtueDescription: "Faith remains close to Christ even when His presence is hidden and there are no easy answers." },
  "jesus-dies": { event: "Jesus dies on the Cross", timeRange: "3:00 PM – 3:59 PM", openingPrayer: prayer("O Jesus Crucified, here I am beneath Your Cross at the hour when You gave everything for me. Teach me to love as You have loved—unto death. Amen."), virtue: "Sacrificial Love", virtueDescription: "Make a concrete act of self-giving today for someone in need, silently and generously." },
  "taken-down": { event: "Jesus is taken down and laid in the arms of His Mother", timeRange: "4:00 PM – 4:59 PM", openingPrayer: prayer("O Holy Spirit, open the eyes of my heart to contemplate this sorrowful beauty. Fill me with compassion, humility, and a share in Mary's sorrow. Amen."), virtue: "Holy Trust", virtueDescription: "Trusting God even when His plan is veiled in pain, uncertainty, or loss.", virtuePrayer: prayer("Jesus, I trust in You. When I cannot see the way ahead, when I feel abandoned, and when I must surrender what I love, teach me Mary's trust. Amen.") },
  "laid-tomb": { event: "Jesus is buried in the tomb", timeRange: "5:00 PM – 6:00 PM", openingPrayer: prayer("Lord Jesus Christ, teach me to enter the silence of this hour, trust Your hidden presence, and hope in the quiet work of God even when all seems lost. Amen."), virtueDescription: "Hope trusts God's promises even when nothing is visible; the tomb is not the end.", virtuePrayer: prayer("Lord Jesus, grant me hope. When I am abandoned or tempted to despair, remind me of Your Resurrection and anchor me in the knowledge that nothing is impossible for God. Amen.") },
  "sacred-silence": { event: "The Day of Sacred Silence", timeRange: "5:30 AM – 6:00 PM", openingPrayer: prayer("Lord Jesus Christ, today the world is silent. Teach me to rest in trust with You and remain faithful in darkness as I wait with Mary for the Resurrection. Amen."), virtue: "Hope", virtueDescription: "Hope is still, trusting, and unseen; it believes in the promise before it is fulfilled.", virtuePrayer: prayer("Lord Jesus, when I wait in darkness, be my hidden light. Anchor me in Your promises and never let me give up on Your love. Amen.") },
  "descends-dead": { title: "Christ Breaks the Chains", subtitle: "The Descent into Hell · Redemption of the Dead", event: "Christ descends to proclaim liberty to the captives", timeRange: "6:00 PM – 11:30 PM", openingPrayer: prayer("Lord Jesus Christ, You descended into the realm of the dead to proclaim liberty to captives and shatter death's gates. Open my heart to the breadth of Your mercy and the triumph of Your Cross. Amen."), virtueDescription: "Hope believes that no situation is beyond God's reach.", virtuePrayer: prayer("Lord Jesus, You are the hope of the hopeless and light in darkness. When I am tempted to despair, remind me that You have conquered even death. Amen.") },
  "mary-name": { event: "The Risen Jesus calls Mary Magdalene by name", timeRange: "5:00 AM – 7:00 AM", openingPrayer: prayer("Risen Lord Jesus, open my heart to the truth and power of Your Resurrection. Call my name as You called Mary, renew my joy, and send me as a witness of life. Amen."), virtue: "Joy", virtueDescription: "Joy is the fruit of a soul that trusts in the victory of the Risen Christ.", virtuePrayer: prayer("Risen Jesus, let Your Resurrection be the source of my joy. Root out fear and discouragement and make me a witness of Easter light. Amen.") },
  "peace-be-to-you": { title: "Appearance in the Upper Room", subtitle: "From Fear to Peace and Mission", event: "The Risen Jesus appears to the disciples in the Upper Room", timeRange: "12:00 PM – 10:00 PM", openingPrayer: prayer("Risen Lord Jesus, You are risen, and hope has been restored. As You opened the Scriptures and offered peace to the Apostles, speak to me now and send me forth in Your light. Amen."), virtue: "Faith", virtueDescription: "Faith lets the words and presence of Jesus reignite the heart in uncertainty.", virtuePrayer: prayer("Lord Jesus, strengthen my faith when I walk in uncertainty. Let Your word be a lamp and Your presence my light. Increase my faith, that it may bear fruit in hope and love. Amen.") },
};

const approvedMeditationFallbacks: Record<string, { meditation: string[]; reflectionQuestions: string[] }> = {
  gethsemane: { meditation: ["It is night in Gethsemane. Jesus enters the garden carrying the weight of the Passion and the sorrow of every human heart, including mine.", "He falls to the ground in agony and brings His fear honestly before the Father. His humanity trembles, yet His love remains unshaken: not My will, but Yours be done.", "The disciples sleep while Jesus keeps watch. He invites me to remain near Him, to bring my burdens into prayer, and to trust the Father's will even when it is painful."], reflectionQuestions: ["What fears or burdens have I not yet brought honestly before the Father?", "Do I choose comfort or prayer when love asks me to remain watchful?", "Do I trust God's will when it asks something painful of me?"] },
  "annas-caiaphas": { meditation: ["Jesus, bound and wearied from betrayal, is led through the night to Annas and then to Caiaphas. The One who created all things walks quietly as a prisoner.", "False witnesses twist the truth, yet Jesus bears injustice with solemn silence. He stands in the place of every soul falsely judged and entrusts Himself to the Father who judges justly.", "His meekness is not weakness. It is the strength of love refusing retaliation, a quiet witness that truth and charity endure when the world turns against them."], reflectionQuestions: ["How do I respond when I am misunderstood or falsely accused?", "Have I stood silently by while someone was wrongly judged?", "Do I trust God's justice when I face injustice?"] },
  "peter-denies": { meditation: ["Jesus stands shackled and silent before the high priests while false witnesses twist His words. His composure speaks more powerfully than their noise.", "Nearby, Peter warms himself by a fire. The courage he promised has faltered, and three denials end with the rooster's cry. Jesus looks upon him with sorrow and love.", "Peter's tears begin the path to redemption. Christ's mercy does not excuse sin; it opens the door for the fallen disciple to return."], reflectionQuestions: ["When have I denied Jesus through my words, actions, or silence?", "Do I remain faithful when following Christ is inconvenient?", "When I fall, do I turn back to Jesus like Peter?"] },
  "mocked-night": { meditation: ["In the middle of the night Jesus is imprisoned, mocked, blindfolded, and beaten without cause. No friend remains near, yet He does not forget those who suffer alone.", "He remains silent, offering this bitter hour in obedience to the Father and in love for us. His hidden suffering reveals a deep solidarity with every person who feels rejected or forgotten.", "When prayer feels empty and consolation disappears, Jesus teaches me to remain faithful in the quiet hours and to draw near to those who suffer in silence."], reflectionQuestions: ["When others suffer in silence, do I draw near or avoid them?", "How do I respond when I feel mocked, rejected, or alone?", "Do I remain faithful when I feel nothing?"] },
  "pilate-herod": { meditation: ["Early in the morning the crowd leads Jesus to Pilate. They distort the truth, while a ruler who sees no guilt lacks the courage to act justly.", "Pilate sends Jesus to Herod, where He is mocked and questioned without reverence. The Judge of the world stands judged by sinful men and answers with silence.", "Jesus accepts false accusation not from weakness, but from burning love. His silence teaches that truth does not need to shout and that the Father remains the final judge."], reflectionQuestions: ["Am I quick to judge without knowing the full truth?", "How do I respond when I am wrongly accused?", "Do I remain faithful in trials, trusting God to defend me?"] },
  "scourged-crowned": { meditation: ["The Innocent One is handed to the soldiers. The scourging, crown of thorns, mockery, and blows reveal the cost of sin and the depth of Christ's love.", "The King of kings is clothed in mockery and the Judge of the world accepts the sentence of men. He does not curse those who wound Him; He carries the pain in silence.", "His interior majesty shines through humiliation. In Jesus I learn that holiness is not measured by applause, but by humble obedience and love."], reflectionQuestions: ["What pride in me resists being humbled?", "How do I respond when others mock me for doing what is right?", "Am I willing to be misunderstood for Christ's sake?"] },
  "carries-cross": { meditation: ["The sun has barely risen when the rough wood is placed upon Jesus' shoulders, already torn by scourging. He stumbles beneath the weight, yet He walks.", "This Cross carries the sin of the world and the weight of my own sins. Jesus chooses this road not only for humanity, but for me, that I might be free.", "With every step He sanctifies suffering and shows that love is stronger than pain. The Cross is not merely a sentence; it is the throne from which salvation is offered."], reflectionQuestions: ["What crosses in my life do I resist carrying?", "Do I see suffering only as something to avoid?", "When burdened, do I unite myself to Jesus or carry it alone?"] },
  "crucifixion-begins": { meditation: ["At the third hour the soldiers stretch Jesus upon the rough wood. His arms are opened wide in an embrace of all humanity.", "The hands that healed and the feet that walked the roads of Galilee are fastened to the Cross, yet no curse escapes His lips. His suffering becomes an offering of forgiveness.", "Jesus is lifted up as the enthronement of Love. With Mary, John, and the faithful, I look upon the One who was pierced and allow His mercy to change me."], reflectionQuestions: ["Do I recognize how my sins wound the heart of Christ?", "How can I embrace suffering as an offering of love?", "When others wound me, do I choose forgiveness?"] },
  "darkness-land": { meditation: ["At noon the sun hides its face and darkness covers the land. The crowd grows quiet as creation trembles before the mystery of the Cross.", "This darkness reaches into every soul that has known sin, yet it is not despair. It is the darkness of mystery where grace is poured out in silence and the Cross becomes the tree of life.", "I remain with Jesus without easy answers, gazing upon Love crucified and trusting that hidden mercy is at work."], reflectionQuestions: ["What have I hidden that needs the light of Christ?", "Do I understand the cost of redemption?", "Can I remain with Jesus in silence when there are no easy answers?"] },
  "jesus-dies": { meditation: ["At the ninth hour Jesus hangs between heaven and earth. Every breath is a sacrifice and every heartbeat reveals the mercy flowing from His wounded Heart.", "He sees not a face in the crowd but a soul loved from all eternity. With one final cry He commends His Spirit to the Father, and the veil is torn.", "Death is defeated not by force but by love. Beneath the Cross I receive this gift and ask what I will give back."], reflectionQuestions: ["What do I need to surrender at the foot of the Cross?", "How can I live in gratitude for Christ's sacrifice?", "Am I willing to love sacrificially and patiently?"] },
  "taken-down": { meditation: ["The Cross stands empty and the crowd has dispersed. Joseph and Nicodemus lower the lifeless Body of Jesus with reverence.", "Mary receives her Son in her arms. Her silence is not defeat; it is the faithful strength of one who continues to say yes even when God's plan is veiled in pain.", "The Pietà reveals offering rather than possession. Mary teaches me to receive sorrow with love and entrust what I cannot understand to God."], reflectionQuestions: ["Do I allow Mary to hold me in my sorrows?", "Do I cling to what I love or surrender it to God?", "How can I imitate Mary's silence and trust?"] },
  "laid-tomb": { meditation: ["As the sun sinks, Joseph comes forward in courage and lays Jesus in a new tomb. The stone is rolled shut and the Savior rests in the earth He created.", "There is no spectacle now, only silence. Yet God is not absent; even in the tomb, grace is at work.", "Faith begins here: believing that God is working when nothing is visible, waiting in hope for the hidden plan of love."], reflectionQuestions: ["Do I trust God in silence and uncertainty?", "When prayer seems unanswered, do I still hope?", "What old part of my life must die so new life can rise?"] },
  "sacred-silence": { meditation: ["Holy Saturday is the day between death and life, loss and hope. The tomb holds the Lord of Life and the world waits.", "The Church does not rush this day. She waits with Mary, trusting without seeing, because silence is not empty when it is filled with divine purpose.", "This sacred silence teaches me to wait actively in faith. What appears still may be the slow unfolding of redemption."], reflectionQuestions: ["How do I respond when God seems silent?", "What area of my life feels like Holy Saturday?", "Can I rest in God's timing while I wait?"] },
  "descends-dead": { meditation: ["After His death, the Body of Jesus lies in the tomb, but His soul descends to the abode of the dead where the righteous await the Redeemer.", "The light of Christ breaks into the shadows. The chains of death shatter and the gates of the underworld are broken open by the King of Glory.", "Christ reaches even the depths so that no one is beyond His reach. He still enters the darkest places of our lives to bring light, raise the fallen, and set prisoners free."], reflectionQuestions: ["Do I trust Christ to bring light into the darkest places of my heart?", "What wound or fear have I kept hidden from God?", "How can I bring hope to someone who feels abandoned?"] },
  "mary-name": { meditation: ["Before dawn Mary comes to the tomb carrying grief, yet love draws her to remain. The stone is rolled away, but confusion and sorrow still fill her heart.", "Jesus comes without spectacle and simply speaks her name. In that instant grief gives way to recognition and joy: the Lord is alive.", "Mary becomes the first witness of the Resurrection. The Risen Christ calls me by name too, raises me from my own tombs, and sends me to carry the message of life."], reflectionQuestions: ["What tombs in my life has Jesus already rolled away?", "Am I attentive to hear Him call my name?", "Do I live as one who truly believes Christ is risen?"] },
  "peace-be-to-you": { meditation: ["Two disciples walk away burdened by sorrow until a Stranger joins them, listens, and opens the Scriptures. Their hearts burn before their eyes recognize Him in the breaking of bread.", "Later Jesus enters the locked room and speaks peace. Fear gives way to joy as He shows His wounds and breathes the Spirit of new creation upon the Apostles.", "The Risen Jesus meets me in disappointment and behind my locked doors. He opens my understanding, gives peace, and sends me into the world with mission."], reflectionQuestions: ["Where am I walking away from hope?", "Do I recognize Jesus walking with me?", "What fear keeps me behind a locked door?"] },
};

// AI-assisted devotional writing for the opening four moments; Scripture is supplied separately.
const openingDays: Partial<Record<string, Pick<SacredMoment, "openingPrayer" | "meditation" | "reflectionQuestions" | "responsePrayer" | "virtueDescription" | "virtuePrayer">>> = {
  "palm-sunday": {
    openingPrayer: "Lord Jesus Christ, as I accompany You into Jerusalem, open my heart to receive You as You are. Quiet my demands and the expectations I place upon You. Let my praise become a willing surrender, and my welcome become a lasting commitment to follow You. Teach me to walk beside You through this Holy Week with humility, attention, and love. Amen.",
    meditation: [
      "Place yourself beside the road into Jerusalem. Garments cover the ground, branches move above the crowd, and voices rise in welcome. Jesus approaches on a humble animal. Matthew invites us to recognize the promised King in this gentle figure, entering the city without the display of force we might expect from earthly power.",
      "The disciples have carried out a simple task: they have brought what Jesus asked for. Their obedience becomes part of this moment of revelation. Consider the small things the Lord has entrusted to you. A duty faithfully completed, an apology offered, or time given to prayer may prepare a place for Him more truly than an impressive promise.",
      "The city asks who Jesus is. Let that question become personal. Do I welcome Him only when His purposes resemble my own? Can I receive a King who asks me to forgive, to serve, and to relinquish control? The praise of Palm Sunday invites a response that reaches beyond this joyful road into the difficult days ahead.",
      "Remain near Him as the procession moves forward. Offer Him the part of your life you most want to manage alone. You do not need to understand every step before taking the next one with Him. Ask for a humble heart that continues to welcome Jesus when following Him requires patience, sacrifice, or an unseen act of love."
    ],
    reflectionQuestions: ["What expectations make it difficult for me to receive Jesus as He reveals Himself?", "Where is He asking me to obey in a small, ordinary responsibility?", "How will I carry today's welcome into a concrete act of humility this week?"],
    responsePrayer: "Jesus, my King, receive the welcome of my imperfect heart. Forgive me for praising You with my lips while resisting You in my choices. Enter the places where pride and fear have closed the door. Give me the courage to follow Your gentle way, to serve without seeking attention, and to remain faithful when the road becomes difficult. Let my life make room for You each day. Amen.",
    virtueDescription: "Humility receives God's gifts with gratitude and accepts the truth about our need for Him. Today, listen without interrupting or perform a helpful task without seeking recognition.",
    virtuePrayer: "Lord Jesus, gentle King, teach me to receive rather than control, to listen rather than insist, and to serve rather than seek praise. Free me from the need to make myself important. Help me find joy in belonging to You and in honoring the people You place before me. Amen."
  },
  "holy-monday": {
    openingPrayer: "Lord Jesus Christ, draw me into the quiet love of the home at Bethany. Help me to attend to Your presence with a grateful and generous heart. Show me what I have withheld through fear, distraction, or the need for approval. May this time of prayer teach me to offer You what is precious and to love the people You entrust to me. Amen.",
    meditation: [
      "Enter the supper at Bethany in prayer. Martha serves, Lazarus sits at table, and Jesus is welcomed among those who know His friendship and His power to give life. Mary approaches with costly ointment, anoints His feet, and wipes them with her hair. John tells us that its fragrance fills the house. Her devotion becomes something everyone present encounters.",
      "Judas objects to the expense, speaking about the poor while concealing his own dishonesty. The contrast invites an examination of the heart. A reasonable-sounding objection can sometimes hide reluctance to give. Ask gently where calculation has narrowed your love, and where concern about appearances has kept you from an honest offering.",
      "Jesus receives Mary's gift and speaks of His burial. The warmth of this supper stands beside the approaching sorrow of His Passion. Mary cannot prevent what is coming, but she can love Him in the time given to her. We, too, cannot remove every suffering. We can offer presence, practical care, and prayer while there is an opportunity to give them.",
      "Consider what generosity asks of you today. It may be your attention to someone who is lonely, help for a person in need, or time set aside to adore Christ. Love for Jesus and care for the poor belong together in the life of His disciple. Let your offering be thoughtful, sincere, and freely given, without demanding that another person measure its worth."
    ],
    reflectionQuestions: ["What precious gift of time, attention, or resources am I reluctant to offer?", "Do my reasons for withholding love sometimes conceal fear or self-interest?", "Whom can I serve today with the attentive generosity Mary shows Jesus?"],
    responsePrayer: "Jesus, You received Mary's offering with tenderness. Receive the love I bring You today, small and imperfect though it is. Forgive my indifference and the excuses that keep me from giving. Teach me to recognize You in prayer and in those who need my care. Make me generous with my attention, faithful in service, and willing to love without keeping an account of what I receive. Amen.",
    virtueDescription: "Generosity offers what we have with love and discernment. Today, give someone your undivided attention or meet a practical need without expecting repayment.",
    virtuePrayer: "Lord Jesus, everything good I possess is a gift. Open my hands and my heart. Help me give wisely and gladly, respecting the dignity of those I serve. Let neither fear nor the desire for praise govern my offering. Teach me the freedom of a generous heart. Amen."
  },
  "holy-tuesday": {
    openingPrayer: "Lord Jesus Christ, You know the strength I desire and the weakness I would rather hide. As I pray over Your warning to Peter, free me from presumption and discouragement. Teach me to depend upon Your grace, to examine my heart honestly, and to remain attentive to the ways You call me to love. Amen.",
    meditation: [
      "In this Holy Tuesday reflection, look ahead to the supper described by John. Jesus is troubled as He speaks of betrayal among His companions. The disciples look at one another, uncertain whom He means. Allow the gravity of this scene to quiet you. It calls for an honest examination of your own discipleship rather than an easy judgment of another person's heart.",
      "Within this sorrowful setting, Jesus gives His disciples the command to love one another. Their belonging to Him will become visible through that love. Consider how you measure your faithfulness. Knowledge, enthusiasm, and good intentions have their place, but love must take shape in the way you speak, forgive, listen, and care for others.",
      "Peter wants to follow Jesus and offers his very life. Jesus answers by foretelling his denial. Peter's confidence cannot yet bear the trial ahead. His story helps us acknowledge that a sincere promise still needs the support of grace. The Lord knows our weakness before we recognize it ourselves, and His warning invites vigilance rather than despair.",
      "Bring Jesus a promise you find difficult to keep. Ask what practical help faithfulness requires: a daily time of prayer, an honest examination of conscience, or a boundary around a recurring temptation. You are invited to depend on Him in each small choice. Let today's prayer become a modest, concrete act of love, carried out with trust in His help."
    ],
    reflectionQuestions: ["Where do I rely on my own resolve without asking for God's help?", "Would the people closest to me recognize my discipleship through my love?", "What daily practice could help me remain watchful in a recurring temptation?"],
    responsePrayer: "Jesus, You know me completely and still call me to follow You. Forgive the pride that makes me overconfident and the fear that makes me hide my failures. Help me to seek Your grace before temptation, to choose love in ordinary moments, and to return promptly when I fall. Make my promises humble and my faithfulness practical. Keep me near You. Amen.",
    virtueDescription: "Vigilance attends to the movements of the heart and seeks God's help before temptation takes hold. Today, pause before a difficult conversation or familiar temptation and ask for grace to respond with love.",
    virtuePrayer: "Lord Jesus, awaken my attention to Your presence. Give me an honest conscience, a patient heart, and the wisdom to recognize what draws me away from You. Let watchfulness grow from trust rather than anxiety. Strengthen me to choose the good that lies before me today. Amen."
  },
  "spy-wednesday": {
    openingPrayer: "Lord Jesus Christ, as I consider the betrayal that draws near, bring light into my own heart. Show me the compromises I excuse and the attachments I protect. Keep me from judging others while refusing to examine myself. Grant me sincere repentance and a faithful love that chooses You in both hidden and visible things. Amen.",
    meditation: [
      "Matthew tells of Judas approaching the chief priests and agreeing to hand Jesus over for thirty pieces of silver. A relationship is reduced to a bargain. Let the scene invite stillness rather than curiosity about motives the Gospel does not fully explain. The question for prayer is what place Jesus holds in your own choices.",
      "We may never speak of selling our loyalty, yet small compromises can make it conditional. Approval can become more important than honesty; convenience can push aside prayer; resentment can make forgiveness seem too costly. Bring one such choice into the light. Name it plainly before Christ, trusting that truthfulness is an opening to His mercy.",
      "The reading moves from the bargain to the preparation of the paschal meal, where Jesus speaks of betrayal. The disciples respond with sorrow and ask whether it could be them. Their question gives us a humble way to pray. Instead of assuming ourselves incapable of failure, we can ask the Lord to reveal where our hearts need conversion.",
      "Stay before Jesus without making excuses or surrendering to shame. The purpose of this examination is to return to Him. Choose one act of fidelity today: keep a promise, repair a dishonest word, or seek reconciliation where it is needed. Ask for the grace to choose Christ again when doing so carries a cost."
    ],
    reflectionQuestions: ["What comfort, approval, or attachment competes with my loyalty to Jesus?", "What small compromise have I begun to excuse as unimportant?", "What act of repentance or reconciliation can express my renewed fidelity today?"],
    responsePrayer: "Jesus, You are worthy of an undivided heart. Forgive the ways I have placed lesser things before You. Bring my hidden compromises into the light of Your mercy, and give me courage to change what needs to change. When I am tempted to bargain with my conscience, help me choose what is true and loving. Let repentance lead me back to You, and make my fidelity steady in the ordinary duties of each day. Amen.",
    virtueDescription: "Fidelity keeps our love for God present in concrete choices, especially when compromise seems easier. Today, honor a neglected commitment or take a practical step toward repairing a wrong.",
    virtuePrayer: "Lord Jesus, strengthen my loyalty to You. Give me honesty when I am tempted to conceal, courage when I am tempted to compromise, and hope when I need to begin again. Help me keep the promises I can keep and seek Your mercy for the ones I have broken. Make my heart constant in love. Amen."
  }
};

export const holyWeekMeditations: SacredMoment[] = seeds.map((moment, index) => ({
  ...moment,
  ...approvedEnhancements[moment.id],
  sequence: index + 1,
  meditation: approvedMeditationFallbacks[moment.id]?.meditation ?? moment.meditation ?? meditation(moment.title, moment.theme, moment.scriptureReference),
  reflectionQuestions: approvedMeditationFallbacks[moment.id]?.reflectionQuestions ?? moment.reflectionQuestions ?? ["Where is Jesus inviting me to remain with Him in this moment?", "What grace do I want to carry into the rest of today?"],
  scriptureReference: holyWeekScripture[moment.id as keyof typeof holyWeekScripture].map(p => p.reference).join("; "),
  scripturePassages: holyWeekScripture[moment.id as keyof typeof holyWeekScripture],
  imageSrc: artworkByMoment[moment.id],
  imageFocalPoint: "center",
  ...openingDays[moment.id],
}));

export const certaintyLabels = {
  scriptural: "Hour noted in Scripture",
  traditional: "Traditional prayer hour",
  approximate: "Approximate devotional chronology",
  untimed: "",
} as const;

export const holyWeekGroups = [...new Set(holyWeekMeditations.map((moment) => moment.liturgicalDay))];
